import{_ as a,C as o,o as n,c as i,j as t,a as s,E as l,a2 as u}from"./chunks/framework.BxGh02fV.js";const q=JSON.parse('{"title":"Assistant de création","description":"","frontmatter":{"title":"Assistant de création"},"headers":[],"relativePath":"guide/create.md","filePath":"guide/create.md"}'),d={name:"guide/create.md"};function c(p,e,g,f,m,h){const r=o("Capture");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"assistant-de-creation",tabindex:"-1"},[s("Assistant de création "),t("a",{class:"header-anchor",href:"#assistant-de-creation","aria-label":'Permalink to "Assistant de création"'},"​")],-1)),e[1]||(e[1]=t("p",null,[s("L'assistant de création amorce un projet Effortless neuf, pas à pas : le projet lui-même, le profil de routage LLM, la pile technique, une structure initiale, puis le déploiement dans vos outils IA. Il s'ouvre depuis le sélecteur, par "),t("strong",null,"Assistant de création"),s(".")],-1)),e[2]||(e[2]=t("p",null,[s("Pour seulement initialiser un dossier, sans assistant, utilisez "),t("strong",null,"Créer…"),s(" dans le sélecteur ("),t("a",{href:"/Effortless/guide/start.html"},"Ouvrir un workspace"),s(").")],-1)),l(r,{name:"assistant-creation",alt:"L'assistant de création, étape 1 Projet : chemin, nom et description du projet"}),e[3]||(e[3]=u('<p>Avant de commencer, décidez du mode de travail et de l&#39;organisation du code : voir <a href="/Effortless/guide/setup.html">Choisir son organisation</a>.</p><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><ul><li><strong>En haut</strong> : cinq étapes numérotées, <strong>Projet</strong>, <strong>Provider</strong>, <strong>Stack</strong>, <strong>Scaffold</strong> et <strong>Déploiement</strong>. Une étape faite est marquée.</li><li><strong>Au centre</strong> : l&#39;étape courante, avec son titre et ce qu&#39;elle fait.</li><li><strong>En bas</strong> : <strong>Annuler</strong> et <strong>Précédent</strong> à gauche ; <strong>Plus tard</strong> (pour passer une étape facultative) et <strong>Suivant</strong> à droite, puis <strong>Terminer</strong> à la dernière étape.</li></ul><p>Chaque étape agit pour de vrai quand vous cliquez sur son bouton : le message de résultat s&#39;affiche sous le bouton, ou l&#39;erreur en rouge.</p><h2 id="les-etapes" tabindex="-1">Les étapes <a class="header-anchor" href="#les-etapes" aria-label="Permalink to &quot;Les étapes&quot;">​</a></h2><h3 id="_1-projet" tabindex="-1">1. Projet <a class="header-anchor" href="#_1-projet" aria-label="Permalink to &quot;1. Projet&quot;">​</a></h3><ol><li>Indiquez le <strong>Chemin du projet</strong>, ou choisissez le dossier avec <strong>Parcourir…</strong>.</li><li>Donnez un <strong>Nom du projet</strong>, et si vous voulez une <strong>Description (optionnel)</strong>.</li><li>Cliquez sur <strong>Initialiser le projet</strong>.</li></ol><p>Cette étape est obligatoire : <strong>Suivant</strong> reste grisé tant que le projet n&#39;est pas initialisé, car toutes les étapes suivantes écrivent dedans. Une fois le projet initialisé, ses champs ne se modifient plus.</p><h3 id="_2-provider" tabindex="-1">2. Provider <a class="header-anchor" href="#_2-provider" aria-label="Permalink to &quot;2. Provider&quot;">​</a></h3><p>Choisissez une <strong>Famille de provider</strong> (<code>claude</code>, <code>gemini</code>, <code>codex</code> ou <code>mistral</code>), puis <strong>Générer le profil</strong>. Effortless écrit un profil de routage LLM depuis le preset de cette famille. Le bouton devient ensuite <strong>Regénérer le profil</strong>. Facultatif.</p><h3 id="_3-stack" tabindex="-1">3. Stack <a class="header-anchor" href="#_3-stack" aria-label="Permalink to &quot;3. Stack&quot;">​</a></h3><p>Le sélecteur de modèle de stack : choisissez un modèle dans <strong>Modèles disponibles</strong>, vérifiez son build et son cycle, renseignez l&#39;<strong>Identifiant de la stack</strong> et les <strong>Variables</strong> requises, puis <strong>Créer la stack</strong>. La stack est créée dans le projet que vous venez d&#39;initialiser : c&#39;est ainsi qu&#39;un module se déclare (voir <a href="/Effortless/guide/modules.html">Modules</a>). Facultatif.</p><h3 id="_4-scaffold" tabindex="-1">4. Scaffold <a class="header-anchor" href="#_4-scaffold" aria-label="Permalink to &quot;4. Scaffold&quot;">​</a></h3><p>La liste des templates du store projet. Sélectionnez-en un, puis <strong>Appliquer le template</strong> : il pose une structure initiale à la racine du projet. Si le store est vide, l&#39;écran l&#39;indique (« Aucun template dans le store projet. ») : passez l&#39;étape. Facultatif.</p><h3 id="_5-deploiement" tabindex="-1">5. Déploiement <a class="header-anchor" href="#_5-deploiement" aria-label="Permalink to &quot;5. Déploiement&quot;">​</a></h3><p>Un <strong>Récapitulatif</strong> reprend les quatre étapes précédentes, chacune suivie de <strong>réalisé</strong> ou <strong>passé</strong> : une étape n&#39;est « réalisée » que si son action a vraiment été faite (une stack créée, par exemple), pas seulement parcourue. En dessous, le panneau MCP &amp; Skills installe le serveur Effortless dans vos assistants IA, comme dans <strong>Préférences</strong> › <strong>MCP &amp; Skills</strong> (<a href="/Effortless/guide/preferences.html">Profil et préférences</a>).</p><h2 id="terminer" tabindex="-1">Terminer <a class="header-anchor" href="#terminer" aria-label="Permalink to &quot;Terminer&quot;">​</a></h2><p><strong>Terminer</strong> vous ramène au sélecteur, sans ouvrir le projet. Ouvrez-le ensuite avec <strong>Ouvrir…</strong>, ou en saisissant son chemin.</p><p><strong>Annuler</strong> quitte l&#39;assistant à tout moment. Ce qui a déjà été exécuté (initialisation, profil, stack, template) reste écrit dans le dossier.</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>Les mêmes étapes existent en verbes MCP : <code>effortless_init</code>, <code>effortless_provider_profile_init</code>, <code>effortless_stack_add</code>, <code>effortless_scaffold_apply_project</code> et <code>effortless_deploy</code>.</p>',21))])}const _=a(d,[["render",c]]);export{q as __pageData,_ as default};
